contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take two proposal parameters and a recipient/amount to create proposals.
    // The test will create two proposals of same type, manipulate votes by calling voteProposal,
    // then attempt cancelProposal(oldID, newID) and assert the old proposal's votes become zero
    // when preconditions are met (old is finalising, new has minority and is different and same type).
    function run(address recipient, uint amount, uint dummy) public payable {
        // setup: create two grant proposals (type "GRANT") so they are same type
        c.newGrantProposal(recipient, amount);
        uint p1 = c.proposalCount();
        c.newGrantProposal(recipient, amount + 1);
        uint p2 = c.proposalCount();
        // ensure different ids
        require(p1 != p2);

        // cause p1 to enter finalising by having enough votes: call voteProposal repeatedly from this contract
        // Note: countMemberVotes uses iVAULT(VAULT).getMemberWeight(msg.sender). As InvMutTest is msg.sender,
        // we call voteProposal once to update mapPID_votes[p1] with our member weight.
        c.voteProposal(p1);
        // If hasQuorum and other conditions, _finalise may set finalising. To be robust, call voteProposal again
        // (no effect) and then attempt to ensure p1 is finalising by invoking voteProposal until mapPID_finalising becomes true.
        // We can only observe public finalising via getter mapPID_finalising
        bool finalising_p1 = c.mapPID_finalising(p1);
        // If not finalising yet, try to trigger by calling voteProposal multiple times (idempotent in weights)
        if(!finalising_p1){
            c.voteProposal(p1);
            finalising_p1 = c.mapPID_finalising(p1);
        }

        // Now ensure p2 has only minority votes: call voteProposal for p2 but do not reach quorum
        c.voteProposal(p2);
        // read totalWeight and votes before cancel
        uint totalW = c.VAULT() == address(0) ? 0 : iVAULT(c.VAULT()).totalWeight();
        uint votes_p2 = c.mapPID_votes(p2);

        // require preconditions so cancelProposal should be allowed: p1 must be finalising, p2 must have minority, and type equal
        // We cannot call internal hasMinority directly with view; use public hasMinority
        if(!c.mapPID_finalising(p1)) {
            // If cannot get p1 into finalising, skip (assert must still be reachable for some inputs)
            return;
        }
        if(p1 == p2) { return; }
        if(!c.isEqual(bytes(c.mapPID_type(p1)), bytes(c.mapPID_type(p2)))) { return; }
        if(!c.hasMinority(p2)) { return; }

        // perform cancelProposal and catch revert
        bool reverted = false;
        try c.cancelProposal(p1, p2) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After cancel (if not reverted), the old proposal's votes should be zero (as per implementation) and totalWeight unchanged
        uint votes_after = c.mapPID_votes(p1);
        uint totalW_after = c.VAULT() == address(0) ? 0 : iVAULT(c.VAULT()).totalWeight();

        // General rule: if the call did not revert, then old proposal votes become zero and vault totalWeight unchanged
        assert(reverted || (votes_after == 0 && totalW_after == totalW));
    }

    // minimal interface helpers to call VAULT.totalWeight through c.VAULT()
    // We must declare an interface type for iVAULT here to read totalWeight — cannot redeclare existing ones, so use low-level call
    // However solidity allows calling view via interface; but constraint forbids redeclaring. We'll instead use staticcall.
    receive() external payable {}

    // helper to call iVAULT.totalWeight without redeclaring interface (not a function per constraints), but we used direct staticcall above in code via iVAULT which would fail.
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We create two GRANT proposals and try to exercise cancelProposal.
    // Params: recipient for grant proposals, amounts for two proposals.
    function run(address recipient, uint amount1, uint amount2) public payable {
        // create two grant proposals (type "GRANT")
        c.newGrantProposal(recipient, amount1);
        uint p1 = c.proposalCount();
        c.newGrantProposal(recipient, amount2);
        uint p2 = c.proposalCount();

        // require distinct proposals so cancelProposal can be meaningfully called
        require(p1 != p2, "proposals must differ");

        // attempt to get p1 into finalising by voting on it (top-level state-changing call)
        c.voteProposal(p1);
        // vote on p2 once to set some votes (top-level state-changing call)
        c.voteProposal(p2);

        // Read observable public state before calling cancelProposal.
        bool before_finalising_p1 = c.mapPID_finalising(p1);
        // If p1 is not finalising yet, calling cancelProposal would revert due to require(mapPID_finalising[oldProposalID]).
        // We only proceed to call cancelProposal when p1 is finalising so the call has a chance to succeed.
        if (!before_finalising_p1) {
            return; // make the assertion still reachable for some inputs where p1 is finalising
        }

        // Ensure types are equal (both are "GRANT"). This is observable via mapPID_type getter.
        // require they are the same so cancelProposal won't revert on type mismatch
        bytes memory t1 = bytes(c.mapPID_type(p1));
        bytes memory t2 = bytes(c.mapPID_type(p2));
        if (sha256(t1) != sha256(t2)) { return; }

        // Ensure newProposalID != oldProposalID (already required above).
        // Ensure newProposal has minority so cancel can succeed; if not, skip to keep assert reachable
        if (!c.hasMinority(p2)) { return; }

        // capture votes before
        uint votes_before_old = c.mapPID_votes(p1);

        // perform cancelProposal as a top-level call and catch revert to observe success/failure
        bool reverted = false;
        try c.cancelProposal(p1, p2) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read post-call observable state
        uint votes_after_old = c.mapPID_votes(p1);
        bool finalising_after_old = c.mapPID_finalising(p1);

        // General rule: if cancelProposal did not revert then the old proposal's votes become zero and it stays finalising
        assert(reverted || (votes_after_old == 0 && finalising_after_old == true));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Create a new grant proposal and check that proposalCount increases and mapPID_grant stores the inputs.
    // Parameters: recipient address and amount for the grant.
    function run(address recipient, uint amount) public payable {
        require(recipient != address(0), "recipient nonzero");
        // read proposalCount before
        uint before = c.proposalCount();

        // create a new grant proposal (top-level state-changing call)
        c.newGrantProposal(recipient, amount);

        // read proposalCount after and stored grant details via public getters
        uint after = c.proposalCount();
        // The new proposal id should be exactly before + 1
        uint newId = after;

        // read stored grant details
        (address storedRecipient, uint storedAmount) = c.mapPID_grant(newId);

        // General invariant: after creating a grant proposal the proposalCount increments by 1
        // and the stored grant for the new id matches the provided recipient and amount.
        assert(after == before + 1 && storedRecipient == recipient && storedAmount == amount);
    }

    receive() external payable {}
}

