contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test entry
    function run(address recipient, uint amount) public payable {
        require(address(c) != address(0));
        // create a new grant proposal
        c.newGrantProposal(recipient, amount);
        // read the proposal id (proposalCount)
        uint pid = c.proposalCount();
        // read votes before voting
        uint votesBefore = c.mapPID_votes(pid);
        // perform voteProposal and catch reverts
        bool reverted;
        uint returnedWeight;
        try c.voteProposal(pid) returns (uint w) {
            reverted = false;
            returnedWeight = w;
        } catch {
            reverted = true;
            returnedWeight = 0;
        }
        // read votes after voting
        uint votesAfter = c.mapPID_votes(pid);
        // read the caller's member weight from the vault via public getter on c
        // we can only observe via c.VAULT() then call iVAULT on that address; but constraints allow only public/external on c.
        // So instead we read the votesAfter-votesBefore and compare to returnedWeight when not reverted.
        // General rule: if voteProposal did not revert then votesAfter == votesBefore + returnedWeight
        assert((reverted == true) || (votesAfter >= votesBefore && votesAfter - votesBefore == returnedWeight));
    }

    receive() external payable { }
}

